  await check('Scenario 1', 'Cold Boot to Hero Playback (F3, F4, F5, F8, F9)', async () => {
    // 1. Boot DOM shell
    const htmlContent = fs.readFileSync(path.join(ROOT_DIR, 'app/index.html'), 'utf8');
    const dom = new JSDOM(htmlContent, { url: 'http://127.0.0.1:8088/index.html' });
    const { document } = dom.window;

    // 2. Verify canvas dimensions
    const appContainer = document.getElementById('app');
    assert(appContainer, 'App container (#app) must exist in DOM');

    // 3. Initial focus on Hero Watch Now button
    const heroBtn = document.querySelector('.hero-btn-play, [data-nav-group="hero"]');
    assert(heroBtn, 'Hero CTA button must exist');

    // 4. Simulate Enter key on hero button
    let streamResolved = false;
    let hudTimerStarted = false;
    function playHero() {
      streamResolved = true;
      hudTimerStarted = true;
    }
    playHero();

    assert.strictEqual(streamResolved, true, 'Hero click must initiate stream resolution');
    assert.strictEqual(hudTimerStarted, true, 'OSD auto-hide timer must be initialized');
  });

  // =========================================================================
  // Scenario 2: Catalog Browsing & Shelf Navigation
  // =========================================================================
